def solution():
    import numpy as np

    # Input adjacency matrix
    A = np.array([[0.64, 0.197, 0.764, 0.0, 0.0], 
                  [0.197, 0.0, 0.529, 0.0, 0.0], 
                  [0.764, 0.529, 0.617, 0.812, 0.0], 
                  [0.0, 0.0, 0.812, 0.068, 0.459], 
                  [0.0, 0.0, 0.0, 0.459, 0.0]])

    n = len(A)
    INF = float('inf')

    # Initialize distance matrix
    dist = np.full((n, n), INF)

    # Initialize predecessor matrix
    pi = np.full((n, n), -1, dtype=int)

    # Set up initial distances and predecessors
    for i in range(n):
        for j in range(n):
            if i == j:
                dist[i][j] = 0
            elif A[i][j] != 0:
                dist[i][j] = A[i][j]
                pi[i][j] = i

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
                    pi[i][j] = pi[k][j]

    # Count the number of finite shortest paths (excluding self-loops)
    count = 0
    for i in range(n):
        for j in range(n):
            if i != j and dist[i][j] < INF:
                count += 1

    return count
